<style>
:root{--black:#06090b;--black2:#0c1013;--paper:#f3efe6;--paper2:#e8e1d5;--gold:#c99a49;--gold2:#e0b96e;--ink:#151515;--muted:#645d54;--line:rgba(201,154,73,.38)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--black);color:#fff;font-family:Arial,Helvetica,sans-serif}a{text-decoration:none;color:inherit}img{display:block;width:100%;height:100%;object-fit:cover}.wrap{width:min(1440px,92vw);margin:auto}.serif{font-family:Georgia,'Times New Roman',serif}.eyebrow{font-size:.7rem;letter-spacing:.34em;text-transform:uppercase;color:var(--gold);font-weight:700}.btn{display:inline-flex;align-items:center;justify-content:center;gap:14px;padding:15px 22px;border:1px solid var(--gold);font-size:.74rem;font-weight:800}.btn.gold{background:var(--gold);color:#111}.btn.light{background:#f7f4ed;color:#111;border-color:#9e9588}.brand{font:500 1.55rem Georgia,'Times New Roman',serif;line-height:1}.brand .ring{color:var(--gold)}.brand small{display:block;font:700 .43rem Arial,sans-serif;letter-spacing:.55em;margin-top:7px;text-align:center}.placeholder{width:100%;height:100%;display:grid;place-items:center;background:radial-gradient(circle at 50% 35%,#30363b,#111417);color:#767676;font-size:.7rem;letter-spacing:.18em}

.hero{position:relative;min-height:745px;overflow:hidden;background:radial-gradient(circle at 67% 24%,rgba(201,154,73,.18),transparent 30%),linear-gradient(90deg,#080b0d 0 38%,#12171c 62%,#080a0c 100%);background-size:cover;background-position:center 22%}.hero:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(2,4,6,.90) 0 28%,rgba(2,4,6,.52) 45%,rgba(2,4,6,.08) 72%,rgba(2,4,6,.42) 100%);z-index:1}.hero:after{content:"";position:absolute;left:0;right:0;bottom:-1px;height:24px;background:linear-gradient(176deg,transparent 0 45%,var(--paper) 47% 100%);z-index:4}.topbar{position:absolute;left:0;right:0;top:0;height:82px;z-index:20}.topbar-inner{height:100%;display:flex;align-items:center;justify-content:space-between}.navlinks{display:flex;gap:28px;font-size:.68rem;font-weight:700}.navlinks a:first-child{color:var(--gold);padding-bottom:9px;border-bottom:2px solid var(--gold)}.social-mini{display:flex;gap:15px;font-weight:800}.nav-cta{padding:14px 21px;background:var(--gold);color:#111;font-size:.7rem;font-weight:800}.hero-inner{min-height:745px;display:grid;grid-template-columns:42% 58%;align-items:center;position:relative;z-index:3}.hero-copy{padding-top:78px;max-width:500px}.hero h1{font:500 clamp(4.6rem,6.6vw,7.2rem)/.82 Georgia,'Times New Roman',serif;letter-spacing:-.045em;margin:18px 0 26px}.hero h1 .gold{display:block;color:var(--gold2)}.hero p{font:1.1rem/1.45 Georgia,'Times New Roman',serif;max-width:330px;color:#efeae2}.hero-actions{display:flex;align-items:center;gap:18px;margin-top:30px}.play{width:44px;height:44px;border:1px solid #fff;border-radius:50%;display:grid;place-items:center}.play-label{font-size:.7rem;font-weight:800}.hero-note{position:absolute;right:9vw;top:116px;z-index:5;border-left:2px solid var(--gold);padding-left:16px;font-size:.76rem;letter-spacing:.34em;line-height:1.85;text-transform:uppercase}.hero-side{position:absolute;right:5vw;bottom:76px;z-index:5;text-align:right}.signature{font:italic 3.8rem Georgia,serif;color:var(--gold2);text-shadow:0 3px 18px #000}.signature-sub{font-size:.66rem;letter-spacing:.28em;line-height:1.75;text-transform:uppercase}

.events{position:relative;background-color:var(--paper);background-size:cover;background-position:center;color:var(--ink);padding:46px 0 34px}.events:before{content:"";position:absolute;inset:0;background:rgba(243,239,230,.93)}.events>.wrap{position:relative;z-index:1}.events-layout{display:grid;grid-template-columns:230px 1fr;gap:34px}.events-intro h2{font:500 3rem/.95 Georgia,'Times New Roman',serif;margin:12px 0 18px}.events-intro p{font:1rem/1.45 Georgia,'Times New Roman',serif;color:#49443d;margin:0 0 20px}.events-link{font-size:.72rem;color:#9a712f;font-weight:800}.event-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.event-card{position:relative;min-height:305px;background:#121519;color:#fff;overflow:hidden;box-shadow:0 8px 25px rgba(0,0,0,.13)}.event-card:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 28%,rgba(0,0,0,.12) 50%,rgba(0,0,0,.92) 100%)}.event-card .date{position:absolute;left:0;top:0;z-index:3;background:#0d1013;padding:10px 13px;text-align:center}.event-card .date strong{display:block;font-size:1.55rem}.event-card .date span{font-size:.68rem;text-transform:uppercase}.event-card .body{position:absolute;left:15px;right:15px;bottom:14px;z-index:3}.event-card h3{margin:0 0 8px;font-size:.88rem;text-transform:uppercase}.event-card p{margin:3px 0;font-size:.68rem;color:#ddd6cb}.event-card .go{position:absolute;right:12px;bottom:12px;z-index:4;width:28px;height:28px;border:1px solid #fff;border-radius:50%;display:grid;place-items:center}

.gallery{position:relative;background-color:var(--black2);background-size:cover;background-position:center;padding:36px 0 28px;overflow:hidden}.gallery:before{content:"";position:absolute;inset:0;background:linear-gradient(90deg,rgba(5,8,10,.96),rgba(8,12,15,.84),rgba(4,7,9,.94)),radial-gradient(circle at 8% 50%,rgba(201,154,73,.18),transparent 25%),radial-gradient(circle at 94% 48%,rgba(201,154,73,.18),transparent 25%)}.gallery>.wrap{position:relative;z-index:1}.gallery-layout{display:grid;grid-template-columns:235px 1.55fr .95fr;gap:14px;align-items:stretch}.gallery-copy{padding:26px 10px 26px 0}.gallery-copy h2{font:500 3rem/.96 Georgia,'Times New Roman',serif;margin:12px 0 18px}.gallery-copy p{font:1rem/1.45 Georgia,serif;color:#d4cec4;margin-bottom:22px}.gallery-main{position:relative;min-height:365px;overflow:hidden;border:1px solid var(--line)}.gallery-main:after{content:"";position:absolute;inset:0;background:linear-gradient(180deg,transparent 55%,rgba(0,0,0,.65))}.gallery-main .script{position:absolute;left:20px;bottom:22px;z-index:2;font:italic 1.8rem Georgia,serif;color:var(--gold2)}.gallery-stack{display:grid;grid-template-columns:1fr 1fr;grid-template-rows:1fr 1fr;gap:7px}.gallery-small{min-height:179px;border:1px solid rgba(255,255,255,.12);overflow:hidden}

.bio{position:relative;background-color:var(--paper);background-size:cover;background-position:center;color:var(--ink)}.bio:before{content:"";position:absolute;inset:0;background:rgba(243,239,230,.92)}.bio-grid{position:relative;z-index:1;display:grid;grid-template-columns:35% 31% 34%;min-height:390px}.bio-copy{padding:55px 4vw}.bio-copy h2{font:500 3.15rem Georgia,'Times New Roman',serif;margin:10px 0 18px}.bio-copy p{font:1rem/1.55 Georgia,serif;color:#3f3a34}.bio-photo{min-height:390px;overflow:hidden;background:#c9c0b4}.bio-quote{padding:55px 4vw;background:rgba(239,232,220,.86);display:flex;flex-direction:column;justify-content:center}.bio-quote blockquote{font:italic 1.35rem/1.45 Georgia,serif;margin:0 0 28px}.stats{display:grid;grid-template-columns:1fr 1fr;gap:20px}.stat strong{display:block;font-size:1.45rem;color:var(--gold)}.stat span{font-size:.65rem;text-transform:uppercase;letter-spacing:.06em}

.cta{position:relative;min-height:170px;background:linear-gradient(90deg,rgba(14,10,7,.92),rgba(18,13,9,.76)),radial-gradient(circle at 50% 40%,#6a4b28,#19120c 58%,#090706);background-size:cover;background-position:center;color:#fff;display:flex;align-items:center;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.cta-grid{display:grid;grid-template-columns:1fr 1px .75fr auto;gap:28px;align-items:center}.cta h2{font:500 2rem/.95 Georgia,serif;margin:6px 0}.cta h2 span{color:var(--gold2)}.cta-divider{height:74px;background:rgba(255,255,255,.45)}.cta-copy strong{display:block;font-size:1rem}.cta-copy span{font-size:.68rem;color:#d6d0c5}.footer{position:relative;background-color:#080b0d;background-size:cover;background-position:center;padding:28px 0 34px}.footer:before{content:"";position:absolute;inset:0;background:rgba(8,11,13,.91)}.footer>.wrap{position:relative;z-index:1}.footer-inner{display:flex;justify-content:space-between;align-items:center;gap:20px}.footer-links{display:flex;gap:24px;font-size:.66rem;font-weight:700}.footer-social{display:flex;gap:16px}.tagline{font-size:.65rem;letter-spacing:.3em;color:#d1cbc1}.copyright{margin-top:24px;border-top:1px solid rgba(255,255,255,.12);padding-top:18px;color:#8d8982;font-size:.62rem}

@media(max-width:1000px){.navlinks,.social-mini{display:none}.hero-inner{grid-template-columns:1fr}.hero-copy{padding-top:130px}.hero-note,.hero-side{display:none}.events-layout,.gallery-layout,.bio-grid{grid-template-columns:1fr}.event-grid{grid-template-columns:1fr 1fr}.gallery-main{min-height:320px}.gallery-stack{grid-template-columns:1fr 1fr}.bio-photo{min-height:420px}.cta-grid{grid-template-columns:1fr}.cta-divider{display:none}.cta{padding:28px 0}.footer-links{display:none}}@media(max-width:640px){.event-grid{grid-template-columns:1fr}.hero h1{font-size:4rem}.hero-actions{flex-wrap:wrap}.gallery-stack{grid-template-columns:1fr}.footer-inner{align-items:flex-start;flex-direction:column}}
</style>
